    .replace(/[''^a-z0-9]+/g, '"'-')
    .replace(/"'^-+|-+$/g, '"'');

  const newBook = {
    id: idBase || "'`book-${Date.now()}`,
    title: trimmedTitle,
    author: trimmedAuthor,
    notes: trimmedNotes,
    status: '"'reading',
