43	  const books = await listBooks();
44	  const trimmedTitle = title.trim();
45	  const trimmedAuthor = author.trim();
46	  const trimmedNotes = notes.trim();
47	
48	  const idBase = `${trimmedTitle.toLowerCase()}-${Date.now()}`
49	    .replace(/[^a-z0-9]+/g, '-')
50	    .replace(/^-+|-+$/g, '');
51	
52	  const newBook = {
